package com.d104.pnt.ui.game.playimport androidx.lifecycle.SavedStateHandleimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.d104.pnt.data.repository.AuthRepositoryimport com.d104.pnt.data.repository.GameSessionEventimport com.d104.pnt.data.repository.GameSessionRepositoryimport com.d104.pnt.domain.model.GameRoleimport com.d104.pnt.navigation.NavArgsimport com.d104.pnt.util.socket.GameSocketManagerimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.firstimport kotlinx.coroutines.launchimport kotlinx.coroutines.withTimeoutOrNullimport javax.inject.Inject@HiltViewModelclass GameRoleViewModel @Inject constructor(    private val authRepository: AuthRepository,    private val gameSocketManager: GameSocketManager,    private val savedStateHandle: SavedStateHandle,    private val gameSessionRepository: GameSessionRepository) : ViewModel() {    private val roomId: Long = savedStateHandle.get<Long>(NavArgs.ROOM_ID) ?: 0L    private val roleName: String = savedStateHandle.get<String>(NavArgs.ROLE) ?: "THIEF"    val role: GameRole = GameRole.fromName(roleName)    private val _flowStatus = MutableStateFlow<GameFlowStatus>(GameFlowStatus.RoleReveal(role))    val flowStatus = _flowStatus.asStateFlow()    private val _connectionStatus = MutableStateFlow<ConnectionStatus>(ConnectionStatus.Connecting)    val connectionStatus = _connectionStatus.asStateFlow()    val connectedCount = gameSessionRepository.connectedCount    val memberCount = gameSessionRepository.memberCount    init {        gameSessionRepository.connectAndJoin(roomId)        setupListeners()        observeRepositoryEvents()    }    private fun observeRepositoryEvents() {        viewModelScope.launch {            gameSessionRepository.eventFlow.collect { event ->                when (event) {                    is GameSessionEvent.GameStarted -> {                        _flowStatus.value = GameFlowStatus.CountDown(event.gameId)                    }                    else -> {}                }            }        }    }    private fun setupListeners() {        gameSocketManager.setOnWillStartGame { gameId, willStartAt ->            _connectionStatus.value = ConnectionStatus.WillStart(willStartAt)        }        gameSocketManager.setOnGameStarted { gameId, startTime ->            _flowStatus.value = GameFlowStatus.CountDown(gameId)        }        gameSocketManager.setOnJoinedRoom { _, _, _, count ->            _connectionStatus.value = ConnectionStatus.Joined            gameSocketManager.syncGameInfo()        }        gameSocketManager.setOnGameInfoSynced { data ->            val status = data.optString("status")            if (status == "STARTED" || status == "START") {                val gameIdFromSync = data.optLong("gameId")                _flowStatus.value = GameFlowStatus.CountDown(gameIdFromSync)            }        }        gameSocketManager.setOnReconnected {            connectAndJoin()        }    }    private fun connectAndJoin() {        viewModelScope.launch {            try {                val token = authRepository.getAccessToken().first()                if (token.isEmpty()) return@launch                gameSocketManager.connect(token)                // 연결 대기                withTimeoutOrNull(5000) {                    while (!gameSocketManager.isConnected()) {                        delay(200)                    }                }                if (gameSocketManager.isConnected()) {                    _connectionStatus.value = ConnectionStatus.Connected                    gameSocketManager.joinGame(roomId)                    delay(2000)                    if (_flowStatus.value is GameFlowStatus.RoleReveal) {                        gameSocketManager.syncGameInfo()                    }                } else {                    _connectionStatus.value = ConnectionStatus.Error("서버와 연결할 수 없습니다.")                }            } catch (e: Exception) {            }        }    }}sealed class GameFlowStatus {    data class RoleReveal(val role: GameRole) : GameFlowStatus()    data class CountDown(val gameId: Long) : GameFlowStatus()}// 연결 상태sealed class ConnectionStatus {    object Connecting : ConnectionStatus()    object Connected : ConnectionStatus()    object Joined : ConnectionStatus()    data class WillStart(val willStartAt: String) : ConnectionStatus()    data class Error(val message: String) : ConnectionStatus()}